ITEMS = [
{"id":"eval_sc_041","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），建筑抗震设防应达到的三水准目标是什么？","gold_clauses":["GB50011-2010_1.0.2"],"gold_values":[],"gold_answer":"根据GB50011-2010第1.0.2条（强制性条文），建筑抗震设防目标为三水准：第一水准——当遭受低于本地区抗震设防烈度的多遇地震影响时，主体结构不受损坏或不需修理可继续使用（小震不坏）；第二水准——当遭受相当于本地区抗震设防烈度的设防地震影响时，主要结构构件保持基本完好（中震可修）；第三水准——当遭受高于本地区抗震设防烈度的罕遇地震影响时，不致倒塌或发生危及生命的严重破坏（大震不倒）。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_042","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），建筑根据使用功能重要性分为几个抗震设防类别？各如何划定？","gold_clauses":["GB50011-2010_3.1.1"],"gold_values":[],"gold_answer":"根据GB50011-2010第3.1.1条，建筑分为四个抗震设防类别：甲类（特殊设防类）——使用上有特殊设施，涉及国家公共安全的重大建筑；乙类（重点设防类）——地震时使用功能不能中断或需尽快恢复的建筑；丙类（标准设防类）——大量的除甲、乙、丁类以外的建筑；丁类（适度设防类）——使用上人员稀少且震损不致产生次生灾害的建筑。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_043","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），8度（0.20g）设计基本地震加速度值对应多遇地震的水平地震影响系数最大值αmax是多少？","gold_clauses":["GB50011-2010_3.2.2"],"gold_values":["0.16"],"gold_answer":"根据GB50011-2010第3.2.2条，设计基本地震加速度为0.20g（8度），对应多遇地震（50年超越概率63.2%）的水平地震影响系数最大值αmax=0.16；罕遇地震αmax=0.90。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_044","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），7度（0.10g）设计基本地震加速度对应多遇地震的水平地震影响系数最大值αmax是多少？","gold_clauses":["GB50011-2010_3.2.2"],"gold_values":["0.08"],"gold_answer":"根据GB50011-2010第3.2.2条，设计基本地震加速度为0.10g（7度），多遇地震水平地震影响系数最大值αmax=0.08。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_045","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），建筑场地共分为几类？Ⅱ类场地如何定义？","gold_clauses":["GB50011-2010_3.3.1"],"gold_values":[],"gold_answer":"根据GB50011-2010第3.3.1条，建筑场地分为Ⅰ₀、Ⅰ₁、Ⅱ、Ⅲ、Ⅳ类，共5类（Ⅰ类细分为Ⅰ₀和Ⅰ₁）。Ⅱ类场地为中硬土，等效剪切波速150＜vs,eq≤250 m/s（覆盖层厚度≥5m）；或岩石类场地vs,eq>500 m/s（且覆盖层厚度＜5m）时为Ⅰ类。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_046","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），在8度（0.20g）、第一组场地、Ⅱ类场地条件下，设计特征周期Tg是多少？","gold_clauses":["GB50011-2010_3.4.1"],"gold_values":["0.35"],"gold_answer":"根据GB50011-2010第3.4.1条表3.4.1，8度第一组、Ⅱ类场地的设计特征周期Tg=0.35s。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_047","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），在7度（0.10g）、第二组场地、Ⅱ类场地条件下，设计特征周期Tg是多少？","gold_clauses":["GB50011-2010_3.4.1"],"gold_values":["0.40"],"gold_answer":"根据GB50011-2010第3.4.1条表3.4.1，7度第二组、Ⅱ类场地的设计特征周期Tg=0.40s（多遇地震）。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_048","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），当建筑楼层的平面扭转不规则时，楼层最大弹性水平位移与楼层两端弹性水平位移平均值之比不宜大于多少？","gold_clauses":["GB50011-2010_3.4.3"],"gold_values":["1.2"],"gold_answer":"根据GB50011-2010第3.4.3条，楼层的最大弹性水平位移与楼层两端弹性水平位移平均值之比不宜大于1.2（扭转不规则的界定）；不大于1.5为不规则限值。超过1.4时应高度重视，超过1.5不允许。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_049","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），对于高度不超过40m、以剪切变形为主且质量和刚度沿高度分布比较均匀的建筑，可采用哪种地震作用计算方法？","gold_clauses":["GB50011-2010_5.1.4"],"gold_values":[],"gold_answer":"根据GB50011-2010第5.1.4条，高度不超过40m、以剪切变形为主且质量和刚度沿高度分布比较均匀的建筑，及近似单质点体系的建筑，可采用底部剪力法（简化方法）计算水平地震作用。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_050","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），采用底部剪力法时，结构总水平地震作用标准值FEk的计算公式是什么？","gold_clauses":["GB50011-2010_5.2.1"],"gold_values":[],"gold_answer":"根据GB50011-2010第5.2.1条，结构总水平地震作用标准值FEk=α₁×Geq，其中α₁为对应于结构基本自振周期T₁的水平地震影响系数，Geq为结构等效总重力荷载代表值（多质点取总重力荷载代表值的85%，单质点取100%）。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_051","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），多遇地震作用下，钢筋混凝土框架结构的弹性层间位移角限值是多少？","gold_clauses":["GB50011-2010_5.5.1"],"gold_values":["1/550"],"gold_answer":"根据GB50011-2010第5.5.1条表5.5.1，多遇地震作用下，钢筋混凝土框架结构的弹性层间位移角限值[θe]≤1/550。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_052","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），多遇地震作用下，框架-剪力墙结构的弹性层间位移角限值是多少？","gold_clauses":["GB50011-2010_5.5.1"],"gold_values":["1/800"],"gold_answer":"根据GB50011-2010第5.5.1条表5.5.1，多遇地震作用下，框架-剪力墙结构和框架-核心筒结构的弹性层间位移角限值[θe]≤1/800。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_053","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），一级抗震等级框架梁，梁端箍筋加密区的长度不应小于多少？","gold_clauses":["GB50011-2010_6.2.3"],"gold_values":["2"],"gold_answer":"根据GB50011-2010第6.2.3条，一级抗震等级框架梁梁端箍筋加密区长度不应小于2倍梁截面高度、500mm及梁净跨的1/4三者的最大值。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_054","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），二级抗震等级框架梁端的纵向受拉钢筋配筋率不应小于多少？","gold_clauses":["GB50011-2010_6.2.2"],"gold_values":["0.3","0.25"],"gold_answer":"根据GB50011-2010第6.2.2条，二级抗震等级框架梁梁端纵向受拉钢筋（梁顶面）的最小配筋率为0.25%和45ft/fy的较大值；三级为0.2%和45ft/fy的较大值。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_055","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），一级抗震等级框架柱的轴压比限值是多少（剪跨比大于2）？","gold_clauses":["GB50011-2010_6.3.6"],"gold_values":["0.65"],"gold_answer":"根据GB50011-2010第6.3.6条表6.3.6，一级抗震等级框架柱（剪跨比大于2的框架柱）轴压比限值为0.65；二级0.75；三级0.85；四级0.90。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_056","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），框架柱截面最小尺寸不应小于多少，且截面长边与短边之比不宜大于多少？","gold_clauses":["GB50011-2010_6.3.3"],"gold_values":["300","3"],"gold_answer":"根据GB50011-2010第6.3.3条，框架柱截面的宽度和高度均不宜小于300mm；圆形截面柱的直径不宜小于350mm；柱截面长边与短边的边长比不宜大于3。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_057","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），框架梁的截面宽度不宜小于多少，且不宜小于柱宽的多少倍？","gold_clauses":["GB50011-2010_6.1.2"],"gold_values":["200","1/2"],"gold_answer":"根据GB50011-2010第6.1.2条，梁的截面宽度不宜小于200mm；梁截面的高宽比不宜大于4；净跨与截面高度之比不宜小于4；梁截面宽度不宜小于支承该梁的柱截面宽度的1/2。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_058","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），框架节点核心区箍筋最大间距，对于一级抗震等级不宜大于多少？","gold_clauses":["GB50011-2010_6.4.1"],"gold_values":["100"],"gold_answer":"根据GB50011-2010第6.4.1条，框架节点核心区箍筋的最大间距，一级抗震等级不宜大于100mm；二、三级不宜大于150mm。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_059","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），框架角柱在地震作用下应如何处理其设计弯矩和剪力？","gold_clauses":["GB50011-2010_6.4.5"],"gold_values":[],"gold_answer":"根据GB50011-2010第6.4.5条，一、二、三级框架的角柱，经调整后的弯矩、剪力设计值应乘以不小于1.10的增大系数，以考虑双向地震和扭转效应对角柱的不利影响。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_060","type":"single_clause","question":"根据《建筑抗震设计规范》（GB50011-2010），抗震设防烈度为9度时，建筑场地应避开地震时可能发生什么危险的地段？","gold_clauses":["GB50011-2010_4.1.6"],"gold_values":[],"gold_answer":"根据GB50011-2010第4.1.6条（强制性条文），选择建筑场地时，应避开抗震危险地段；对于抗震危险地段，严禁建造甲、乙类建筑，不应建造丙类建筑。危险地段包括：地震时可能发生滑坡、崩塌、地陷、地裂、泥石流的地段；地震断裂带上可能发生地表错位的部位。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_061","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），地基基础设计等级分为哪几级，甲级如何界定？","gold_clauses":["GB50007-2011_3.0.2"],"gold_values":[],"gold_answer":"根据GB50007-2011第3.0.2条，地基基础设计分为甲、乙、丙三个设计等级。甲级包括：重要工业与民用建筑；30层以上或高度超过100m的高层建筑；体型复杂、层数相差超过10层的高低层连成一体的建筑；大面积堆料或填土的地基等情况。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_062","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），地基承载力特征值的深度修正和宽度修正公式是什么？","gold_clauses":["GB50007-2011_5.1.3"],"gold_values":[],"gold_answer":"根据GB50007-2011第5.1.3条，修正后的地基承载力特征值fa=fak+ηb·γ·(b-3)+ηd·γm·(d-0.5)，其中fak为土的承载力特征值，ηb、ηd为修正系数，γ为基础底面以下土的重度，b为基础底面宽度（m，＜3取3、＞6取6），γm为基础底面以上土的加权平均重度，d为基础埋置深度（m）。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_063","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），甲级设计等级的建筑物地基变形计算中，对高层建筑物还需计算什么？","gold_clauses":["GB50007-2011_5.2.4"],"gold_values":[],"gold_answer":"根据GB50007-2011第5.2.4条，甲级建筑物地基变形计算除沉降量外，还需计算倾斜（沉降差/距离之比），对高层建筑物尤为重要。此外还需验算整体倾斜，基础中心点与基础两端的沉降差不超过规范限值。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_064","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），基础的埋置深度一般不宜小于多少？","gold_clauses":["GB50007-2011_4.1.1"],"gold_values":["0.5"],"gold_answer":"根据GB50007-2011第4.1.1条，基础的埋置深度，应满足地基强度和变形的要求，一般天然地基上的基础埋深不宜小于0.5m（不包括地面坡度等特殊情况的要求）。","should_refuse":False,"source":"Claude生成","difficulty":"easy"},
{"id":"eval_sc_065","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），软弱下卧层地基承载力验算的关键公式中，压力扩散角θ如何取值（条形基础，z/b=0.25）？","gold_clauses":["GB50007-2011_5.2.3"],"gold_values":["6"],"gold_answer":"根据GB50007-2011第5.2.3条表5.2.3，软弱下卧层验算中地基压力扩散角θ的取值与z/b（持力层厚度/基础宽度）和土层条件有关；对于条形基础，当z/b=0.25时，粉土、砂土一般取θ≈6°，黏性土取θ≈0°（需内插）。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_066","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），建筑物的整体倾斜控制标准，对于高宽比H/B大于4的高层建筑，整体倾斜不应大于多少？","gold_clauses":["GB50007-2011_5.3.1"],"gold_values":["0.002"],"gold_answer":"根据GB50007-2011第5.3.1条表5.3.4，高宽比H/B大于4的高层建筑，地基变形引起的整体倾斜不应超过0.002（即不超过建筑高度的2‰）。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_067","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），地下室工程中，当地下水位高于基础底面时，应验算什么？","gold_clauses":["GB50007-2011_8.5.1"],"gold_values":[],"gold_answer":"根据GB50007-2011第8.5.1条，当建筑物存在水位高于基础底面的情况时，应进行抗浮稳定验算。抗浮稳定性验算：建筑物自重及其他荷载与地下水浮力的比值（抗浮稳定系数Kf）不应小于1.05；当不满足时应采取抗浮措施（抗浮桩、抗浮锚杆等）。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_068","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），大面积地面荷载对基础沉降和承载力有影响时，基底附加压力的计算应扣除什么？","gold_clauses":["GB50007-2011_5.1.1"],"gold_values":[],"gold_answer":"根据GB50007-2011第5.1.1条，基础底面的压力（基底反力）应满足：基底平均压力p≤fa（修正后的地基承载力特征值）。基底附加压力p0=p-γm·d，即扣除基础自重和基础上土的自重（即扣除原来的自重应力）。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_069","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），在季节性冻土地区，建筑基础埋深应考虑什么因素？","gold_clauses":["GB50007-2011_4.1.3"],"gold_values":[],"gold_answer":"根据GB50007-2011第4.1.3条，在季节性冻土地区，基础埋置深度应符合当地标准冻结深度的要求，通常不宜小于该地区设计冻结深度加上安全厚度（保护层厚度），具体取当地设计冻深以下一定值，以防止冻胀力危害基础。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_070","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），扩展基础（独立基础和条形基础）中，当基础底面积不够大时，需要扩展，扩展基础受冲切承载力验算的公式是？","gold_clauses":["GB50007-2011_8.5.3"],"gold_values":[],"gold_answer":"根据GB50007-2011第8.5.3条，基础受冲切承载力应满足：Fl≤βhp·ft·am·h0，其中Fl为冲切力，βhp为截面高度影响系数，ft为混凝土抗拉强度设计值，am为冲切破坏锥体最不利侧面的计算长度，h0为基础截面的有效高度。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_071","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），基础的最小配筋率要求是什么（扩展基础底板）？","gold_clauses":["GB50007-2011_6.3.1"],"gold_values":["0.15"],"gold_answer":"根据GB50007-2011第6.3.1条，扩展基础的受力钢筋直径不宜小于10mm，间距不宜大于200mm，也不宜小于100mm；底板受力钢筋的最小配筋率不应小于0.15%。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_072","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），地基基础设计中，乙级建筑物需要进行地基变形验算的条件是什么？","gold_clauses":["GB50007-2011_3.0.3"],"gold_values":[],"gold_answer":"根据GB50007-2011第3.0.3条，地基基础设计等级为乙级（即标准设计等级、不属于甲级、丙级）的建筑物，在满足地基承载力要求的同时，需进行地基变形验算，尤其当地基土的压缩性较高、建筑对沉降较敏感时。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_073","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），条形基础埋置深度不小于多少才能保证基础稳定性（不考虑冻深和水位）？","gold_clauses":["GB50007-2011_4.1.4"],"gold_values":["0.5"],"gold_answer":"根据GB50007-2011第4.1.4条，连续墙基础（条形基础）的埋置深度，室内地面以下不宜小于0.5m（大型工业厂房）；室外地面以下不宜小于0.3m，以防止基础因雨水浸蚀或人为扰动而不稳定。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_074","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），对于相邻的基础，当荷载大小相差较大时，可能出现什么问题，规范如何要求？","gold_clauses":["GB50007-2011_5.3.4"],"gold_values":[],"gold_answer":"根据GB50007-2011第5.3.4条，相邻建筑物基础荷载相差较大时，可能产生不均匀沉降（差异沉降），引起结构倾斜或损坏。规范要求控制沉降差，对于丙级建筑，相邻柱基的差异沉降量与其距离之比不应超过0.002（框架结构）。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
{"id":"eval_sc_075","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），地基反力计算中，中心荷载作用下，基础底面的压力分布如何简化？","gold_clauses":["GB50007-2011_5.1.1"],"gold_values":[],"gold_answer":"根据GB50007-2011第5.1.1条，在中心荷载作用下，基础底面的压力（地基反力）可简化为均匀分布，即p=（F+G）/A，其中F为柱（墙）传来的竖向荷载，G为基础及其上土的重量，A为基础底面积。","should_refuse":False,"source":"Claude生成","difficulty":"easy"},
{"id":"eval_sc_076","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），桩基础的设计竖向承载力特征值Ra如何由单桩极限承载力标准值Quk确定？","gold_clauses":["GB50007-2011_6.3.1"],"gold_values":["2"],"gold_answer":"根据GB50007-2011第6.3.1条，单桩竖向承载力特征值Ra=Quk/2，即为单桩竖向极限承载力标准值的一半（安全系数K=2）。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_077","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），地基持力层的选择有何要求？","gold_clauses":["GB50007-2011_4.1.5"],"gold_values":[],"gold_answer":"根据GB50007-2011第4.1.5条，持力层（直接支承基础的土层）应选择承载力高、变形小的土层；宜选用稳定的硬土层、中硬土层或密实粗砂；对于软弱土层，应采取换填、加固等处理措施或采用深基础。","should_refuse":False,"source":"Claude生成","difficulty":"easy"},
{"id":"eval_sc_078","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），基础底面积的确定应综合考虑哪两个方面的要求？","gold_clauses":["GB50007-2011_5.1.1"],"gold_values":[],"gold_answer":"根据GB50007-2011第5.1.1条，基础底面积应满足两方面要求：①地基承载力要求（基础底面压力不超过地基承载力特征值fa）；②地基变形要求（建筑的沉降量和差异沉降量不超过规范限值）。二者均需满足，取较大面积。","should_refuse":False,"source":"Claude生成","difficulty":"easy"},
{"id":"eval_sc_079","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），对于地下水位高于基础底面的情况，地基承载力计算时地基土重度如何取用？","gold_clauses":["GB50007-2011_4.1.6"],"gold_values":[],"gold_answer":"根据GB50007-2011第4.1.6条，在计算地基承载力修正时，当地下水位以下的土层，其重度应取浮重度（有效重度）γ'=γsat-γw，约取9~11 kN/m³，以反映地下水对土层有效应力的影响。","should_refuse":False,"source":"Claude生成","difficulty":"medium"},
{"id":"eval_sc_080","type":"single_clause","question":"根据《建筑地基基础设计规范》（GB50007-2011），对于地基承载力特征值，当基础宽度超过3m时，需进行宽度修正，修正系数ηb的取值与什么有关？","gold_clauses":["GB50007-2011_5.1.3"],"gold_values":[],"gold_answer":"根据GB50007-2011第5.1.3条表5.1.3，地基承载力宽度修正系数ηb与地基土的性质有关：淤泥和淤泥质土ηb=0；e≥0.85的黏性土ηb=0；粉土、e<0.85的黏性土、粉砂ηb=0.3；细砂ηb=0.5；中粗砂ηb=1.0；砾砂、角砾、碎石ηb=2.0。","should_refuse":False,"source":"Claude生成","difficulty":"hard"},
]

